PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "__drizzle_migrations" (
				id INTEGER PRIMARY KEY,
				hash text NOT NULL,
				created_at numeric,
				name text,
				applied_at TEXT
			);
CREATE TABLE `actors` (
	`id` text PRIMARY KEY,
	`kind` text NOT NULL,
	`host` text DEFAULT '' NOT NULL,
	`session` text DEFAULT '' NOT NULL,
	`name` text,
	`person_id` text,
	`external_ref` text,
	`created_at` text NOT NULL
) STRICT;
CREATE TABLE `annotations` (
	`id` text PRIMARY KEY,
	`thread_id` text NOT NULL,
	`project_id` text NOT NULL,
	`first_seq` integer NOT NULL,
	`seq` integer NOT NULL
) STRICT;
CREATE TABLE `answers` (
	`id` text PRIMARY KEY,
	`question_id` text NOT NULL,
	`author_id` text NOT NULL,
	`via_actor_id` text,
	`answer` text,
	`revision` integer NOT NULL,
	`state` text NOT NULL,
	`sent_reply_id` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	`seq` integer NOT NULL
) STRICT;
CREATE TABLE `attachments` (
	`id` text NOT NULL,
	`message_id` text NOT NULL,
	`name` text NOT NULL,
	`kind` text NOT NULL,
	`size` integer,
	`sha256` text NOT NULL,
	`created_at` text,
	CONSTRAINT `attachments_pk` PRIMARY KEY(`message_id`, `id`)
) STRICT;
CREATE TABLE `cards` (
	`id` text PRIMARY KEY,
	`project_id` text NOT NULL,
	`first_seq` integer NOT NULL,
	`seq` integer NOT NULL,
	`card` text NOT NULL,
	`heard_seq` integer NOT NULL
) STRICT;
CREATE TABLE `events` (
	`id` integer PRIMARY KEY,
	`seq` integer NOT NULL,
	`at` text NOT NULL,
	`v` integer NOT NULL,
	`kind` text NOT NULL,
	`subject_id` text NOT NULL,
	`project_id` text,
	`thread_id` text,
	`message_id` text,
	`actor_id` text,
	`data` text NOT NULL
) STRICT;
CREATE TABLE `initiatives` (
	`id` text PRIMARY KEY,
	`first_seq` integer NOT NULL,
	`seq` integer NOT NULL
) STRICT;
CREATE TABLE `mentions` (
	`message_id` text NOT NULL,
	`position` integer NOT NULL,
	`target_actor_id` text NOT NULL,
	`label` text,
	`wakes` integer,
	CONSTRAINT `mentions_pk` PRIMARY KEY(`message_id`, `position`)
) STRICT;
CREATE TABLE `message_tags` (
	`message_id` text NOT NULL,
	`tag_key` text NOT NULL,
	`thread_id` text NOT NULL,
	`project_id` text NOT NULL,
	`seq` integer NOT NULL,
	CONSTRAINT `message_tags_pk` PRIMARY KEY(`message_id`, `tag_key`)
) STRICT;
CREATE TABLE `messages` (
	`id` text PRIMARY KEY,
	`thread_id` text NOT NULL,
	`project_id` text NOT NULL,
	`reply_to` text,
	`author_id` text NOT NULL,
	`via_actor_id` text,
	`created_at` text NOT NULL,
	`first_seq` integer NOT NULL,
	`seq` integer NOT NULL,
	`subject` text,
	`body` text NOT NULL
) STRICT;
CREATE TABLE `meta` (
	`key` text PRIMARY KEY,
	`value` text NOT NULL
) STRICT;
CREATE TABLE `projects` (
	`id` text PRIMARY KEY,
	`key` text NOT NULL,
	`root` text NOT NULL,
	`name` text NOT NULL,
	`first_seq` integer NOT NULL,
	`seq` integer NOT NULL,
	`deleted_at` text
) STRICT;
CREATE TABLE `questions` (
	`id` text PRIMARY KEY,
	`message_id` text NOT NULL,
	`thread_id` text,
	`project_id` text NOT NULL,
	`key` text NOT NULL,
	`kind` text NOT NULL,
	`prompt` text NOT NULL,
	`revision` integer NOT NULL,
	`sent_revision` integer NOT NULL,
	`current_answer_id` text,
	`sent_reply_id` text,
	`asked_by_actor_id` text,
	`first_seq` integer NOT NULL,
	`seq` integer NOT NULL
) STRICT;
CREATE TABLE `read_state` (
	`thread_id` text NOT NULL,
	`actor_id` text NOT NULL,
	`seen_seq` integer,
	`read_seq` integer,
	`read_at` text,
	`seq` integer NOT NULL,
	CONSTRAINT `read_state_pk` PRIMARY KEY(`thread_id`, `actor_id`)
) STRICT;
CREATE TABLE `steps` (
	`id` text PRIMARY KEY,
	`thread_id` text,
	`project_id` text,
	`first_seq` integer NOT NULL,
	`seq` integer NOT NULL
) STRICT;
CREATE TABLE `thread_names` (
	`root_id` text NOT NULL,
	`seq` integer NOT NULL,
	`project_id` text NOT NULL,
	`name` text NOT NULL,
	`routes` integer NOT NULL,
	CONSTRAINT `thread_names_pk` PRIMARY KEY(`root_id`, `seq`)
) STRICT;
CREATE TABLE `thread_pull_events` (
	`id` integer PRIMARY KEY,
	`seq` integer NOT NULL,
	`thread_id` text NOT NULL,
	`project_id` text NOT NULL,
	`event` text NOT NULL
) STRICT;
CREATE TABLE `thread_pulls` (
	`id` text PRIMARY KEY,
	`thread_id` text,
	`project_id` text,
	`first_seq` integer NOT NULL,
	`seq` integer NOT NULL
) STRICT;
CREATE TABLE `threads` (
	`id` text PRIMARY KEY,
	`project_id` text NOT NULL,
	`thread_name` text,
	`resolved_at` text,
	`resolved_seq` integer,
	`readdressed` integer DEFAULT false NOT NULL,
	`first_seq` integer NOT NULL,
	`last_seq` integer NOT NULL,
	`last_at` text NOT NULL,
	`message_count` integer NOT NULL,
	`seq` integer NOT NULL,
	`deleted_at` text
) STRICT;
CREATE UNIQUE INDEX `actors_identity` ON `actors` (`kind`,`host`,`session`);
CREATE INDEX `annotations_thread` ON `annotations` (`thread_id`);
CREATE INDEX `annotations_seq` ON `annotations` (`seq`);
CREATE UNIQUE INDEX `answers_author` ON `answers` (`question_id`,`author_id`);
CREATE INDEX `answers_seq` ON `answers` (`seq`);
CREATE INDEX `attachments_sha` ON `attachments` (`sha256`);
CREATE INDEX `cards_project` ON `cards` (`project_id`);
CREATE INDEX `cards_seq` ON `cards` (`seq`);
CREATE INDEX `events_seq` ON `events` (`seq`);
CREATE INDEX `events_subject` ON `events` (`kind`,`subject_id`,`seq`);
CREATE INDEX `events_project` ON `events` (`project_id`);
CREATE INDEX `events_thread` ON `events` (`thread_id`);
CREATE INDEX `events_message` ON `events` (`message_id`);
CREATE INDEX `initiatives_seq` ON `initiatives` (`seq`);
CREATE INDEX `mentions_target` ON `mentions` (`target_actor_id`);
CREATE INDEX `message_tags_thread` ON `message_tags` (`thread_id`);
CREATE INDEX `message_tags_project` ON `message_tags` (`project_id`);
CREATE INDEX `message_tags_seq` ON `message_tags` (`seq`);
CREATE INDEX `messages_thread` ON `messages` (`thread_id`,`first_seq`);
CREATE INDEX `messages_seq` ON `messages` (`seq`);
CREATE INDEX `projects_key` ON `projects` (`key`);
CREATE INDEX `projects_seq` ON `projects` (`seq`);
CREATE INDEX `questions_message` ON `questions` (`message_id`);
CREATE INDEX `questions_thread` ON `questions` (`thread_id`);
CREATE INDEX `questions_seq` ON `questions` (`seq`);
CREATE INDEX `steps_thread` ON `steps` (`thread_id`);
CREATE INDEX `steps_project` ON `steps` (`project_id`);
CREATE INDEX `steps_seq` ON `steps` (`seq`);
CREATE INDEX `thread_names_project` ON `thread_names` (`project_id`);
CREATE INDEX `thread_names_seq` ON `thread_names` (`seq`);
CREATE INDEX `thread_pull_events_thread` ON `thread_pull_events` (`thread_id`,`seq`);
CREATE INDEX `thread_pull_events_project` ON `thread_pull_events` (`project_id`);
CREATE INDEX `thread_pulls_thread` ON `thread_pulls` (`thread_id`);
CREATE INDEX `thread_pulls_project` ON `thread_pulls` (`project_id`);
CREATE INDEX `thread_pulls_seq` ON `thread_pulls` (`seq`);
CREATE INDEX `threads_project` ON `threads` (`project_id`);
CREATE INDEX `threads_last` ON `threads` (`last_seq`);
CREATE INDEX `threads_seq` ON `threads` (`seq`);
COMMIT;
